TS_BITS = 32; MAX_TS = 2^32 - 1
def encode(points, reached_at_epoch_s):
    return points * 2^TS_BITS + (MAX_TS - reached_at_epoch_s)   // < 2^53 stays exact
def decode(v):
    return int(v) >> TS_BITS

