def top_n(board, n):
    parts = parallel([r.zrevrange(key(board, i), 0, n-1, withscores=True)
                      for i, r in enumerate(shards)])
    return heapq.nlargest(n, chain(*parts), key=lambda x: x.score)

def rank(board, user, score):
    return 1 + sum(parallel([r.zcount(key(board, i), f'({score}', '+inf')
                             for i, r in enumerate(shards)]))
